(()=>{
let mode='agents',current=null;
const menu=document.getElementById('agent-menu'),options=document.getElementById('agent-options'),search=document.getElementById('agent-search'),toggle=document.getElementById('agent-toggle');
function groups(){if(window.REGIONAL_WORKSPACES?.[sessionStorage.getItem('yunxu-role')])return REGIONAL_WORKSPACES[sessionStorage.getItem('yunxu-role')].groups;if(sessionStorage.getItem('yunxu-role')==='inventory-accountant')return window.INVENTORY_ACCOUNTING_GROUPS||[];if(isOpsRole())return OPS_GROUPS;if(isWarehouseRole())return WAREHOUSE_GROUPS;return composerAgents.filter(a=>a[0]!=='auto').map(a=>{const matching=WAREHOUSE_GROUPS.find(g=>g.name===a[1]||({'inventory':'inventory-ops-agent','purchase':'purchase-fulfillment-agent','order':'order-ops-agent'})[a[0]]===g.id);return {id:a[0],name:a[1],desc:a[2],skills:matching?.skills||(a[0]==='payable'?payableComposerSkills.map(s=>s.name):erpSkillCatalog.map(s=>s.name.replace(' Skill','')))}})}
function select(g,skill){selectedComposerAgent=g.id;toggle.textContent=skill?g.name+' · '+skill:g.name;toggle.title=skill?g.name+' · '+skill:g.name;toggle.dataset.selectedAgent=g.id;toggle.dataset.selectedSkill=skill||'';current=g}
function chooseSkill(g,skill){select(g,skill);closeAgentMenu();suggest('请使用'+g.name+'的“'+skill+'”技能，协助处理相关业务。');promptBox.focus()}
function direct(g){openNewConversation();document.getElementById('conversation-recommendations')?.remove();document.body.classList.remove('conversation-entry');select(g);document.getElementById('title').textContent=g.name;document.getElementById('subtitle').textContent=g.desc;document.getElementById('crumb').textContent='AI对话';addMessage('你好，我是'+g.name+'。请描述需要处理的事项，我可以协助：'+g.skills.join('、')+'。当前为交互演示。',false);closeAgentMenu();promptBox.focus()}
function render(){const q=search.value.trim();const heading=menu.querySelector('.skill-menu-title');heading.replaceChildren();if(mode==='skills'&&current){const back=document.createElement('button');back.type='button';back.className='agent-skill-back';back.textContent='‹ 返回智能体';back.onclick=e=>{e.stopPropagation();mode='agents';search.value='';render()};heading.append(back);const label=document.createElement('strong');label.textContent=current.name+' · 选择技能';heading.append(label);options.innerHTML=current.skills.filter(s=>s.includes(q)).map((s,i)=>'<button type="button" class="agent-nested-skill" data-skill-index="'+current.skills.indexOf(s)+'"><span aria-hidden="true">▦</span><strong>'+escapeHTML(s)+'</strong></button>').join('')||'<p class="agent-picker-empty">暂无匹配技能</p>';options.querySelectorAll('[data-skill-index]').forEach(b=>b.onclick=()=>chooseSkill(current,current.skills[Number(b.dataset.skillIndex)]));search.placeholder='搜索该智能体的技能';return}
heading.textContent='选择智能体';search.placeholder='搜索智能体';const list=groups().filter(g=>(g.name+g.desc).includes(q));options.innerHTML=list.map((g,i)=>'<article class="composer-agent-card" tabindex="0"><div class="composer-agent-summary"><span class="composer-agent-icon"><img src="assets/role-asset-admin-avatar.webp" width="32" height="32" alt=""></span><div><strong>'+escapeHTML(g.name)+'</strong><p>'+escapeHTML(g.desc)+'</p></div></div><div class="composer-agent-actions"><button type="button" data-direct="'+i+'">直接对话</button><button type="button" data-choose="'+i+'">选择技能</button></div></article>').join('')||'<p class="agent-picker-empty">暂无匹配智能体</p>';options.querySelectorAll('[data-direct]').forEach(b=>b.onclick=()=>direct(list[Number(b.dataset.direct)]));options.querySelectorAll('[data-choose]').forEach(b=>b.onclick=e=>{e.stopPropagation();current=list[Number(b.dataset.choose)];mode='skills';search.value='';render();search.focus()})}
renderAgentOptions=render;
const originalToggle=toggleAgentMenu;toggleAgentMenu=function(){if(menu.hidden){mode='agents';search.value=''}originalToggle()};
search.addEventListener('input',render);
const reset=openNewConversation;openNewConversation=function(){reset();mode='agents';current=null;delete toggle.dataset.selectedAgent;delete toggle.dataset.selectedSkill;toggle.title='选择智能体';toggle.textContent='✧ 选择智能体'};
})();
